  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Butuh Editor yang Cepat dan Ringan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Notepad bawaan Windows terlalu sederhana, sedangkan aplikasi berat seperti Word atau IDE makan banyak memori dan lama dibuka. Untuk mengedit kode, file konfigurasi, catatan cepat, atau log server, kita butuh editor yang dibuka dalam sekejap, ringan, tetapi tetap punya fitur canggih.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Apa Itu Notepad++$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Notepad++ adalah editor teks gratis dan open source untuk Windows. Ia mendukung pewarnaan sintaks (syntax highlighting) untuk puluhan bahasa pemrograman, tab ganda, pencarian dengan regex, macro, dan ribuan plugin. Ukurannya kecil dan berjalan cepat bahkan di komputer tua.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$Komputer Windows (7/10/11)$txt$, $txt$Koneksi internet untuk mengunduh installer$txt$, $txt$File teks/kode yang ingin diedit$txt$, $txt$Waktu 10 menit untuk instalasi dan tur fitur$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah-langkah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Unduh installer dari situs resmi notepad-plus-plus.org, pilih versi 64-bit sesuai sistem.$txt$, $txt$Jalankan installer, ikuti wizard standar, dan biarkan opsi konteks menu aktif agar bisa klik kanan file lalu "Edit with Notepad++".$txt$, $txt$Buka sebuah file kode dan perhatikan pewarnaan sintaks otomatis berdasarkan ekstensi file.$txt$, $txt$Coba tab ganda: klik kanan tab lalu "Move to Other View" untuk melihat dua file berdampingan.$txt$, $txt$Gunakan Ctrl+F untuk pencarian biasa dan Ctrl+H untuk ganti teks; aktifkan mode regex untuk pola rumit.$txt$, $txt$Rekam macro lewat menu Macro > Start Recording untuk pekerjaan berulang, lalu putar ulang dengan Ctrl+Shift+P.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Fitur Penting yang Jarang Diketahui$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$txt$Multi-editing: tahan Alt lalu seret untuk memilih kolom teks vertikal.$txt$, $txt$Plugin Compare untuk membandingkan dua file berdampingan.$txt$, $txt$Session snapshot: file yang belum disimpan tetap aman walau aplikasi tertutup mendadak.$txt$, $txt$Find in Files (Ctrl+Shift+F) untuk mencari teks di seluruh folder proyek.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Risiko dan Hal yang Perlu Diperhatikan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Notepad++ hanya tersedia resmi untuk Windows; versi lain biasanya tidak resmi. Jangan mengedit file sistem atau registry tanpa cadangan, karena satu kesalahan ketik bisa merusak konfigurasi. Selalu simpan salinan sebelum mengubah file penting.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Pergelangan Tangan Nyeri Mengganggu Aktivitas$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Nyeri di pergelangan tangan membuat mengetik, mengangkat barang, bahkan memutar gagang pintu jadi menyakitkan. Keluhan ini umum pada pekerja kantoran, pengendara motor, dan siapa pun yang tangannya dipakai berulang-ulang setiap hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Penyebab yang Paling Sering$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 3, to_jsonb(ARRAY[$txt$Strain/terkilir: ligamen tertarik karena jatuh dengan tangan menahan badan atau gerakan memutar mendadak.$txt$, $txt$Tendinitis: peradangan tendon akibat gerakan berulang seperti mengetik atau menggunakan mouse berjam-jam.$txt$, $txt$Sindrom terowongan karpal: saraf medianus terjepit, ditandai kesemutan dan mati rasa di ibu jari hingga jari tengah.$txt$, $txt$Artritis: peradangan sendi, lebih sering pada usia lanjut.$txt$, $txt$Ganglion: benjolan berisi cairan sendi yang menekan jaringan sekitar.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan: Yang Perlu Disiapkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$Kompres dingin (es dibungkus handuk)$txt$, $txt$Perban elastis atau wrist support bila ada$txt$, $txt$Obat pereda nyeri bebas sesuai aturan pakai$txt$, $txt$Meja dan kursi dengan posisi ergonomis$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Penanganan Mandiri$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Istirahatkan tangan: hentikan aktivitas yang memicu nyeri selama 1-2 hari.$txt$, $txt$Kompres dingin 15 menit, 2-3 kali sehari pada 48 jam pertama untuk mengurangi bengkak.$txt$, $txt$Balut ringan dengan perban elastis agar sendi stabil, jangan terlalu kencang.$txt$, $txt$Posisikan tangan lebih tinggi dari jantung saat berbaring untuk mengurangi bengkak.$txt$, $txt$Lakukan peregangan lembut setelah nyeri berkurang: tekuk pergelangan perlahan ke atas dan bawah, tahan 15 detik.$txt$, $txt$Perbaiki ergonomi: keyboard sejajar siku, mouse pas di genggaman, dan istirahat 5 menit tiap 30 menit mengetik.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Kapan Harus ke Dokter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Segera konsultasikan ke dokter bila nyeri hebat setelah jatuh atau benturan, tangan bengkak dan berubah bentuk, mati rasa yang tidak hilang, demam menyertai nyeri sendi, atau nyeri tidak membaik setelah dua minggu perawatan mandiri. Artikel ini bersifat informasi umum dan bukan pengganti nasihat medis profesional.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pencegahan Jangka Panjang$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Latih kekuatan pergelangan dengan bola remas, gunakan pelindung saat olahraga berisiko jatuh, dan jaga postur kerja. Bila pekerjaan menuntut gerakan berulang, pertimbangkan alat bantu ergonomis dan jadwal istirahat teratur.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Siapa Orang Batak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Batak adalah kelompok etnis besar di Sumatera Utara yang terdiri dari beberapa sub-suku: Toba, Karo, Simalungun, Pakpak, Angkola, dan Mandailing. Mereka dikenal tegas, terbuka, dan sangat menjunjung tinggi ikatan kekeluargaan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sistem Marga: Identitas yang Diwariskan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Setiap orang Batak memiliki marga yang diwariskan dari garis ayah (patrilineal), seperti Siregar, Nasution, Simbolon, atau Ginting. Marga bukan sekadar nama belakang: ia menentukan siapa saudara, siapa yang boleh dinikahi, dan bagaimana seseorang bersikap dalam upacara adat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Dalihan Na Tolu: Tiga Tungku Kekerabatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Falsafah hidup Batak bertumpu pada Dalihan Na Tolu, tiga pilar hubungan sosial: somba marhula-hula (hormat kepada keluarga pihak istri), elek marboru (kasih sayang kepada pihak yang menikahi putri keluarga), dan manat mardongan tubu (hati-hati dan setia kepada sesama semarga). Ketiganya menjaga keseimbangan sosial dalam setiap hajatan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Larangan Menikah Semarga$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pernikahan sesama marga dilarang karena dianggap menikahi saudara sendiri. Aturan ini, yang disebut eksogami marga, memperluas jaringan kekerabatan antar-keluarga dan memperkuat persatuan antar-marga dari generasi ke generasi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Upacara Adat dan Ulos$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Dalam kelahiran, pernikahan, hingga kematian, kain ulos selalu hadir sebagai simbol kehangatan dan berkat. Upacara adat Batak memadukan doa, musik gondang, dan torttor, serta kini sering berjalan berdampingan dengan ibadah agama yang dianut keluarga.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Mengenal Xenon$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Xenon (simbol Xe, nomor atom 54) adalah gas mulia yang ditemukan pada 1898 oleh William Ramsay dan Morris Travers. Di atmosfer Bumi ia sangat langka, hanya sekitar 0,000009 persen, dan diperoleh lewat distilasi udara cair.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat yang Istimewa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Seperti gas mulia lain, xenon sangat tidak reaktif sehingga aman dicampur dalam berbagai peralatan. Ia tidak berwarna, tidak berbau, dan memiliki massa jenis jauh lebih berat daripada udara. Keunikan inilah yang membuatnya berguna di banyak bidang.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Dari Lampu hingga Proyektor$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Lampu xenon menghasilkan cahaya putih terang menyerupai siang hari, dipakai di lampu depan mobil premium, proyektor bioskop, dan lampu kilat fotografi. Cahayanya stabil dan tajam karena pelepasan listrik di dalam gas xenon bertekanan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Anestesi Medis$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Xenon dipakai sebagai gas anestesi karena bekerja cepat dan pasien pulih dengan cepat setelah operasi, dengan efek samping yang relatif ringan. Kendalanya adalah harga yang sangat mahal, sehingga pemakaiannya terbatas pada fasilitas tertentu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Mesin Ion Wahana Antariksa$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Wahana antariksa memakai xenon sebagai bahan bakar pendorong ion: atom xenon diionisasi lalu disemburkan dengan kecepatan tinggi. Cara ini sangat hemat bahan bakar untuk misi antarplanet yang berlangsung bertahun-tahun.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, kamu diharapkan mampu mengidentifikasi struktur discussion text, memahami ciri kebahasaannya, dan menulis discussion text sederhana tentang isu sehari-hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Discussion Text$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Discussion text adalah teks yang menyajikan dua sudut pandang (pro dan kontra) tentang suatu isu, lalu diakhiri dengan kesimpulan atau rekomendasi penulis. Tujuannya memberi pembaca gambaran utuh sebelum mengambil sikap.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Struktur Discussion Text$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$Issue: pernyataan tentang isu yang akan dibahas.$txt$, $txt$Arguments for (pro): alasan-alasan yang mendukung isu.$txt$, $txt$Arguments against (kontra): alasan-alasan yang menentang isu.$txt$, $txt$Conclusion/recommendation: simpulan atau saran penulis.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Ciri Kebahasaan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Simple present tense; kata penghubung: firstly, secondly, finally, however, on the other hand, although.$txt$, $txt$Kosa kata evaluatif: important, harmful, beneficial, risky.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh Singkat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Issue: Should students bring mobile phones to school? Arguments for: phones help students contact parents in emergencies and access learning apps. Arguments against: phones distract students during lessons and enable cheating. Conclusion: phones may be allowed but must be switched off during class.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$txt$1. What is the purpose of a discussion text? Jawab: menyajikan dua sudut pandang tentang suatu isu lalu diakhiri simpulan.$txt$, $txt$2. Mention the generic structure of a discussion text! Jawab: issue, arguments for, arguments against, conclusion/recommendation.$txt$, $txt$3. Write two arguments for and two against: "Homework should be abolished." (Contoh) For: more free time, less stress. Against: less practice, lower discipline.$txt$]));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, kamu bisa menentukan faktor suatu bilangan, menemukan faktor persekutuan dua bilangan, dan menentukan FPB dengan dua cara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Faktor dan Faktor Persekutuan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Faktor adalah bilangan-bilangan yang dapat membagi habis suatu bilangan. Contoh: faktor dari 12 adalah 1, 2, 3, 4, 6, dan 12, karena semuanya membagi 12 tanpa sisa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 4, jsonb_build_object('text', $$Faktor persekutuan adalah faktor yang dimiliki bersama oleh dua bilangan atau lebih. Contoh: faktor 8 adalah 1, 2, 4, 8; faktor 12 adalah 1, 2, 3, 4, 6, 12. Faktor persekutuannya adalah 1, 2, dan 4.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 5, jsonb_build_object('text', $$Menentukan FPB: Dua Cara$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 6, jsonb_build_object('text', $$Cara 1 (himpunan faktor): tulis semua faktor kedua bilangan, lingkari yang sama, pilih yang terbesar. Contoh: FPB dari 8 dan 12 adalah 4.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Cara 2 (pohon faktor): buat pohon faktor tiap bilangan sampai tersisa bilangan prima.$txt$, $txt$Contoh: 18 = 2 x 3 x 3; 24 = 2 x 2 x 2 x 3.$txt$, $txt$Ambil faktor prima yang sama dengan pangkat terkecil: 2 x 3 = 6.$txt$, $txt$Jadi, FPB dari 18 dan 24 adalah 6.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh Soal Cerita$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Ibu punya 20 apel dan 30 jeruk yang akan dibagikan ke kantong dengan isi sama banyak. Berapa kantong terbanyak yang bisa dibuat? FPB dari 20 dan 30 adalah 10, jadi ada 10 kantong, masing-masing berisi 2 apel dan 3 jeruk.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$txt$1. Tentukan FPB dari 15 dan 25! Jawab: 5 (faktor 15: 1,3,5,15; faktor 25: 1,5,25).$txt$, $txt$2. Tentukan FPB dari 28 dan 42 dengan pohon faktor! Jawab: 28 = 2x2x7; 42 = 2x3x7; FPB = 2x7 = 14.$txt$, $txt$3. Ada 24 buku dan 36 pensil untuk dibagikan sama rata ke beberapa anak. Berapa anak terbanyak? Jawab: FPB(24,36) = 12 anak.$txt$]));
